//! Conditional native environment factory over the shared source-bound policy.
use super::{HttpPlan, emit};
use crate::{OutFile, credential_env::CredentialEnvKind};
use serde_json::json;

pub(super) fn artifacts(plan: &HttpPlan) -> Vec<OutFile> {
    let Some(policy) = plan.credential_env() else {
        return Vec::new();
    };
    let factory = plan
        .credential_env_factory()
        .expect("bound policy has allocated factory");
    let mut code = format!(
        "// Code generated by suspect. DO NOT EDIT.\npackage sdk\n\nimport \"os\"\n\n// {factory} snapshots the explicitly configured environment variables once.\n// Missing, empty or unusable values remain missing credentials; protected\n// operations report their normal source-bound error before HTTP.\n// NewClient always uses its complete explicit credential argument instead.\n// Supply zero or one ClientOptions; the source server is the default.\nfunc {factory}(options ...ClientOptions) (*Client, error) {{\n\tif len(options) > 1 {{ return nil, &SDKError{{Kind: \"request-representation\"}} }}\n\tvar option ClientOptions\n\tif len(options) == 1 {{ option = options[0] }}\n\tcredentials := Credentials{{}}\n"
    );
    for binding in policy.bindings() {
        let (guard, method) = match binding.kind() {
            CredentialEnvKind::Bearer => ("validBearer", "WithBearer"),
            CredentialEnvKind::ApiKey => ("httpHeaderValue", "WithAPIKey"),
        };
        code.push_str(&format!("\tif value, found := os.LookupEnv({}); found && len(value) > 0 && len(value) <= {} && {guard}(value) {{\n\t\tcredentials = credentials.{method}({}, value)\n\t}}\n",emit::q(binding.variable()),plan.config().max_request_bytes,emit::q(binding.name())));
    }
    code.push_str("\treturn NewClient(credentials, option)\n}\n");
    vec![OutFile{path:"go/http_environment.go".into(),content:code},OutFile{path:"go/credential-env.json".into(),content:format!("{}\n",serde_json::to_string_pretty(&json!({"factory":factory,"semantics":policy.semantic_descriptor(),"sourceBindings":policy})).unwrap())}]
}

pub(super) fn readme(plan: &HttpPlan) -> String {
    let Some(policy) = plan.credential_env() else {
        return String::new();
    };
    let factory = plan.credential_env_factory().expect("bound factory");
    let mut text = format!(
        "\n## Environment credential factory\n\n```go\nclient, err := sdk.{factory}()\nif err != nil {{ return err }}\ndefer client.CloseIdleConnections()\n```\n\nPass one `ClientOptions` to inject a `Doer`, timeout or explicit server override. With no options, the source server is used. This factory snapshots only these explicitly configured variable names:\n\n"
    );
    for binding in policy.bindings() {
        text.push_str(&format!(
            "- `{}` supplies source scheme `{}` ({:?}).\n",
            binding.variable(),
            binding.name(),
            binding.kind()
        ));
    }
    text.push_str("\nGeneration and package import read no environment values. Changing a variable affects a new factory-created client, not an existing client. Missing, empty or unusable values stay missing; anonymous operations can still run, and protected operations return their normal secret-free `SDKError` before HTTP. Source OR/AND and explicit alternative selection are unchanged.\n\n`NewClient(credentials, options)` remains wholly explicit: empty credentials, an empty token, or an omitted member never fall back to environment values. Go's typed credential argument does not accept `nil`. No `.env` discovery, token acquisition, refresh or per-request environment access is added. `credential-env.json` records names and source binding only.\n");
    text
}
